// ─── LABELS ─────────────────────────────────────────────────────────────────
export const LICHT_LABELS = { 1: 'Sonnig', 2: 'Halbschatten', 3: 'Schatten' }
export const WASSER_LABELS = { 1: 'Trocken', 2: 'Mäßig feucht', 3: 'Feucht' }
export const BODEN_LABELS = { sandy: 'Sandig', loamy: 'Lehmig', clay: 'Tonig', humus: 'Humusreich' }
export const TYPE_LABELS = { staude: 'Staude', strauch: 'Strauch', gras: 'Gras', einjährig: 'Einjährig', zweijährig: 'Zweijährig', baum: 'Baum' }
export const DRAINAGE_LABELS = { durchlässig: 'Durchlässig (Sand/Kies)', normal: 'Normal (Lehm)', stauend: 'Stauend (Ton/nass)' }
export const WUCHSFORM_LABELS = { aufrecht: 'Aufrecht', polster: 'Polster', kriechend: 'Kriechend/Bodendecker', strauch: 'Strauch/Gehölz', baum: 'Baum' }
export const MONTHS = ['Jan','Feb','Mär','Apr','Mai','Jun','Jul','Aug','Sep','Okt','Nov','Dez']

// ─── FILTER ─────────────────────────────────────────────────────────────────
export function filterPlants({ licht, wasser, boden, types, wuchsform, drainage, ph, searchTerm } = {}) {
  return PLANTS.filter(p => {
    if (licht && !p.licht.includes(licht)) return false
    if (wasser && !p.wasser.includes(wasser)) return false
    if (boden && !p.boden.includes(boden)) return false
    if (types && types.length && !types.includes(p.type)) return false
    if (wuchsform && p.wuchsform !== wuchsform) return false
    if (drainage && p.drainage !== drainage) return false
    if (ph && (p.ph_min > ph || p.ph_max < ph)) return false
    if (searchTerm) {
      const s = searchTerm.toLowerCase()
      if (!p.name.toLowerCase().includes(s) && !p.latin.toLowerCase().includes(s) &&
          !p.beschreibung?.toLowerCase().includes(s)) return false
    }
    return true
  })
}
